package com.bank.partition.partition;

import java.nio.charset.StandardCharsets;

// Mirrors Kafka's "hash of key modulo partition count". Kafka uses murmur2;
// here we use a stable hash to demonstrate the distribution behaviour.
public class BankPartitioner {
    private final int numPartitions;

    public BankPartitioner(int numPartitions) { this.numPartitions = numPartitions; }

    public int partitionFor(String key) {
        if (key == null) return 0; // real Kafka uses sticky/round-robin for null keys
        int h = murmur2(key.getBytes(StandardCharsets.UTF_8));
        // mask off sign bit, then modulo partitions (same idea as Kafka)
        return (h & 0x7fffffff) % numPartitions;
    }

    // Simplified murmur2 for demonstration.
    private int murmur2(byte[] data) {
        int seed = 0x9747b28c;
        int m = 0x5bd1e995;
        int r = 24;
        int h = seed ^ data.length;
        int len = data.length;
        int i = 0;
        while (len >= 4) {
            int k = (data[i] & 0xff) | ((data[i + 1] & 0xff) << 8)
                  | ((data[i + 2] & 0xff) << 16) | ((data[i + 3] & 0xff) << 24);
            k *= m; k ^= k >>> r; k *= m;
            h *= m; h ^= k;
            i += 4; len -= 4;
        }
        switch (len) {
            case 3: h ^= (data[i + 2] & 0xff) << 16;
            case 2: h ^= (data[i + 1] & 0xff) << 8;
            case 1: h ^= (data[i] & 0xff); h *= m;
        }
        h ^= h >>> 13; h *= m; h ^= h >>> 15;
        return h;
    }
}
