package com.bank.partition;

import com.bank.partition.model.Transfer;
import com.bank.partition.partition.BankPartitioner;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PartitionDemo {
    private static final Logger log = Logger.getLogger(PartitionDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int partitions = 12;
        BankPartitioner partitioner = new BankPartitioner(partitions);

        // Build 10000 transfers where 90% are from WEST region.
        List<Transfer> transfers = new ArrayList<>();
        Random rnd = new Random(42);
        String[] regions = {"WEST", "EAST", "NORTH", "SOUTH"};
        for (int i = 0; i < 10000; i++) {
            String region = rnd.nextInt(10) < 9 ? "WEST" : regions[rnd.nextInt(4)];
            transfers.add(new Transfer("ACC" + i, region, new BigDecimal("1000")));
        }

        int[] byRegion = new int[partitions];
        int[] byAccount = new int[partitions];
        for (Transfer t : transfers) {
            byRegion[partitioner.partitionFor(t.getRegion())]++;      // BAD key
            byAccount[partitioner.partitionFor(t.getAccountId())]++;  // GOOD key
        }

        log.warning("Keyed by REGION (low cardinality) -> " + Arrays.toString(byRegion));
        log.severe("Hot partition detected: one partition holds most records.");
        log.info(() -> "Keyed by ACCOUNT ID (high cardinality) -> " + Arrays.toString(byAccount));
        log.info("Even spread: all 12 partitions share the load.");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
